    public void resettle(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches) throws InvalidClaimStatusChangeException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward re-settles a claim");
        }
        if (claim.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be re-settled");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot be re-settled");
        }
        Person person = people.find(sheet, claim.person());
        BigDecimal was = claim.settledDue() == null ? null : new BigDecimal(claim.settledDue());
        BigDecimal due = claim.asOpenUnbound().due(rates.list(sheet), person.gradeOn(claim.date()),
                settings.floor(sheet), settings.late(sheet, clock.today(sheet)));
        Rollup.Snapshot before = rollup.take(sheet);
        if (!claims.resettle(sheet, claim.id(), was, due)) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        log.record(sheet, user, claim.id());
        audit.record("CLAIM_RESETTLED sheet=" + sheet + " by=" + user + " " + claim.statusAuditFields(person.name())
                + " old=" + (was == null ? "n/a" : was.toPlainString())
                + " new=" + (due == null ? "n/a" : due.toPlainString()));
        watches.notify(sheet, user, person.id(), person.name(), claim.shownNumber());
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.delegation.Delegations;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The roles given per sheet, by user name; a name given none is a clerk. A user lent the steward role acts as one
 *  while the sheet's today is inside the delegation. */
@Repository
public class Roles {

    private static final RowMapper<Role> ROW = (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;
    private final Delegations delegations;
    private final SheetClock clock;

    public Roles(JdbcTemplate jdbc, Delegations delegations, SheetClock clock) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.clock = clock;
    }

    /** Every role given on the sheet, by user name. */
    public List<Role> list(String sheet) {
        return jdbc.query("SELECT user_name, role FROM user_role WHERE sheet = ? ORDER BY user_name", ROW, sheet);
    }

    /** The role the user acts in on the sheet: steward while lent the role, else the role given. */
    public String of(String sheet, String user) {
        if (delegations.delegatorOn(sheet, user, clock.today(sheet)).isPresent()) {
            return Role.STEWARD;
        }
        return given(sheet, user);
    }

    /** The user's role given on the sheet: clerk unless given another. */
    public String given(String sheet, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM user_role WHERE sheet = ? AND user_name = ?",
                String.class, sheet, user);
        return found.isEmpty() ? Role.CLERK : found.get(0);
    }

    public void set(String sheet, Role role) {
        jdbc.update("MERGE INTO user_role (sheet, user_name, role) KEY (sheet, user_name) VALUES (?, ?, ?)", sheet,
                role.user(), role.role());
    }
}
