import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useFloorCents } from '../settings/settings';
import { useClaims, useLate } from '../claims/claims';
import { personPeriodDueCents, shownPersonDueTotal, usePeriods } from './periods';

function PeriodHeaders({ sheet }: { sheet: string; user: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name} due</th>
      ))}
    </>
  );
}

// Per period on the sheet, the person's due-total for it: the due now of their claims whose date falls in it that counted at its end,
// fixed for everyone on the sheet when the period is closed (0.00 for a person added since). The period's own
// due-total is the sum of these.
function PersonPeriods({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);

  const totals = personPeriodDueCents(periods, claims, people, rates, floor, late);

  return (
    <>
      {periods.map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {shownPersonDueTotal(p, person.id, totals.get(p.name)?.get(person.id) ?? 0n)}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 15, Component: PeriodHeaders }),
  PersonColumns.fill({ order: 15, Component: PersonPeriods }),
];
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Soft-closes the period: its due-total and each person's are fixed now as a close fixes them, but claims dated in it
 * may still be added, edited and change status (one added meanwhile is a late entry). Refuses a role the permission
 * matrix does not let close, a period not on the sheet, or one already closed or soft-closed.
 */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheet") String sheet, @PathVariable("period") String period,
            @RequestParam("user") String user, Periods periods, PeriodCloser closer, Settings settings,
            Roles roles)
            throws InvalidPeriodException {
        if (!settings.permits(sheet, "close", roles.of(sheet, user))) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        Period found = periods.find(sheet, period);
        if (found == null) {
            throw new InvalidPeriodException("There is no period named " + period);
        }
        if (found.fixed() || !closer.close(sheet, user, found, false, true)) {
            throw new InvalidPeriodException("The period " + period + " is already closed");
        }
    }
}

